import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { UserList } from './UserList';
import { fetchUsers } from '../services/userApi';

jest.mock('../services/userApi');
const mockedFetchUsers = jest.mocked(fetchUsers);

describe('UserList', () => {
  beforeEach(() => {
    mockedFetchUsers.mockReset();
  });

  it('renderiza estado de carregamento inicialmente', () => {
    render(<UserList />);

    expect(screen.getByRole('status')).toHaveTextContent('Carregando usuários...');
  });

  it('renderiza mensagem de erro ao falhar carregamento', async () => {
    mockedFetchUsers.mockRejectedValue(new Error('Erro de rede'));
    render(<UserList />);

    expect(await screen.findByRole('alert')).toHaveTextContent('Falha ao carregar usuários: Erro de rede');
  });

  it('renderiza lista de usuários quando carregamento é bem-sucedido', async () => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    mockedFetchUsers.mockResolvedValue(users);
    render(<UserList />);

    const list = await screen.findByRole('list', { name: 'Usuários' });
    expect(list).toBeInTheDocument();
    expect(screen.getByText('Alice')).toBeInTheDocument();
    expect(screen.getByText('Bob')).toBeInTheDocument();
  });

  it('renderiza mensagem quando não há usuários cadastrados', async () => {
    mockedFetchUsers.mockResolvedValue([]);
    render(<UserList />);

    expect(await screen.findByText('Nenhum usuário cadastrado.')).toBeInTheDocument();
  });

  it('filtra usuários com base na consulta de pesquisa', async () => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    mockedFetchUsers.mockResolvedValue(users);
    render(<UserList />);

    await userEvent.type(screen.getByLabelText('Filtrar'), 'Alice');
    expect(screen.getByText('Alice')).toBeInTheDocument();
    expect(screen.queryByText('Bob')).not.toBeInTheDocument();
  });

  it('renderiza mensagem quando nenhum usuário é encontrado na pesquisa', async () => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    mockedFetchUsers.mockResolvedValue(users);
    render(<UserList />);

    await userEvent.type(screen.getByLabelText('Filtrar'), 'Charlie');
    expect(screen.getByText('Nenhum usuário encontrado para “Charlie”.')).toBeInTheDocument();
  });
});

